if (integration.provider_id === 'geotab') {
    const { username, database, password } = integration.credentials;
    const auth = await axios.post("https://my.geotab.com/apiv1", {
      method: "Authenticate",
      params: { userName: username, password: password, database: database }
    });
    if (auth.data.error) throw new Error(auth.data.error.message);

    const credentials = auth.data.result.credentials;
    const serverPath = auth.data.result.path === "ThisServer" ? "my.geotab.com" : auth.data.result.path;

    // Fetch Devices to map IDs to friendly names
    const deviceRes = await axios.post(`https://${serverPath}/apiv1`, {
      method: "Get",
      params: { typeName: "Device", credentials }
    });
    const allDevices = deviceRes.data.result || [];
    const deviceMap = {};
    allDevices.forEach(d => { deviceMap[d.id] = d.name; });

    const response = await axios.post(`https://${serverPath}/apiv1`, {
      method: "Get",
      params: { typeName: "DeviceStatusInfo", search: {}, credentials }
    });

    const locations = response.data.result || [];
    if (locations.length === 0) throw new Error("Trigger Fallback");

    const mapData = locations.map(loc => ({
      id: loc.device.id,
      vehicle_number: deviceMap[loc.device.id] || loc.device.name || loc.device.serialNumber || "Vehicle " + loc.device.id,
      lat: loc.latitude,
      lng: loc.longitude,
      speed: loc.speed,
      is_moving: loc.isDeviceMoving,
      last_updated: loc.dateTime
    }));

    console.log("📍 [DEBUG] Live Tracking sample location:", JSON.stringify(mapData.slice(0, 2)));
    console.log("📍 [DEBUG] Data source confirmed as:", integration.provider_id, "| Raw Geotab response count:", locations.length);

    return res.json({ success: true, data: mapData });
}

