app.post('/api/live-zones', async (req, res) => {
  const { organizationId } = req.body;

  try {
    const { data: integrations, error: integrationErr } = await supabase
      .from('fleet_integrations')
      .select('provider_id, credentials')
      .eq('organization_id', organizationId)
      .eq('status', 'connected');

    if (integrationErr || !integrations || integrations.length === 0) {
      return res.json({ success: true, data: [] });
    }

    const provider = integrations.find(p => p.provider_id === 'geotab');
    if (!provider || !provider.credentials) {
      return res.json({ success: true, data: [] });
    }

    const { username, database, password } = provider.credentials;
    const auth = await axios.post("https://my.geotab.com/apiv1", {
      method: "Authenticate",
      params: { userName: username, password: password, database: database }
    });
    if (auth.data.error) throw new Error(auth.data.error.message);

    const credentials = auth.data.result.credentials;
    const serverPath = auth.data.result.path === "ThisServer" ? "my.geotab.com" : auth.data.result.path;

    const response = await axios.post(`https://${serverPath}/apiv1`, {
      method: "Get",
      params: { typeName: "Zone", credentials }
    });

    const zones = response.data.result || [];
    const formattedZones = zones.map(z => ({
      id: z.id,
      name: z.name,
      lat: z.centroid ? z.centroid.y : null,
      lng: z.centroid ? z.centroid.x : null
    })).filter(z => z.lat !== null && z.lng !== null);

    console.log("📍 [DEBUG] Fetched Geotab zones count:", formattedZones.length);

    return res.json({ success: true, data: formattedZones });

  } catch (err) {
    console.error("❌ Live Zones Error:", err.message);
    return res.json({ success: true, data: [] });
  }
});

