app.post('/api/geotab-risk-report', async (req, res) => {
    try {
        const { organizationId } = req.body;
        if (!organizationId) return res.json({ success: true, data: [] });

        const { data: integrations, error: integrationErr } = await supabase
          .from('fleet_integrations')
          .select('provider_id, credentials')
          .eq('organization_id', organizationId)
          .eq('status', 'connected');

        if (integrationErr || !integrations || integrations.length === 0) {
            console.log("📡 [DEBUG] No active telematics integrations for risk report. Returning empty.");
            return res.json({ success: true, data: [] });
        }

        const riskData = [];
        const toDate = new Date();
        const fromDate = new Date();
        fromDate.setDate(fromDate.getDate() - 30); // 30 day risk evaluation

        for (const integration of integrations) {
            console.log(`📡 [DEBUG] Risk Report calling provider: ${integration.provider_id}`);
            try {
                if (integration.provider_id === 'geotab') {
                    const { username, password, database } = integration.credentials;
                    const auth = await axios.post("https://my.geotab.com/apiv1", {
                        method: "Authenticate",
                        params: { userName: username, password: password, database: database }
                    });
                    if (auth.data.error) throw new Error(auth.data.error.message);

                    const credentials = auth.data.result.credentials;
                    const serverPath = auth.data.result.path === "ThisServer" ? "my.geotab.com" : auth.data.result.path;

                    // Fetch active devices
                    const devicesRes = await axios.post(`https://${serverPath}/apiv1`, {
                        method: "Get",
                        params: { typeName: "Device", credentials }
                    });
                    const devices = devicesRes.data.result || [];

                    for (const d of devices.slice(0, 10)) { // Limit to 10 for performance
                        // 1. Calculate Distance from Trips
                        const tripsRes = await axios.post(`https://${serverPath}/apiv1`, {
                            method: "Get",
                            params: {
                                typeName: "Trip",
                                search: { deviceSearch: { id: d.id }, fromDate: fromDate.toISOString(), toDate: toDate.toISOString() },
                                credentials
                            }
                        });
                        const trips = tripsRes.data.result || [];
                        const totalDistKm = trips.reduce((sum, t) => sum + (t.distance || 0), 0);
                        const distanceMiles = Math.round(totalDistKm * 0.621371);

                        // 2. Calculate Idling from ExceptionEvents
                        const exceptionsRes = await axios.post(`https://${serverPath}/apiv1`, {
                            method: "Get",
                            params: {
                                typeName: "ExceptionEvent",
                                search: {
                                    deviceSearch: { id: d.id },
                                    fromDate: fromDate.toISOString(),
                                    toDate: toDate.toISOString(),
                                    ruleSearch: { id: "RuleIdlingId" }
                                },
                                credentials
                            }
                        });
                        const exceptions = exceptionsRes.data.result || [];
                        let totalIdleSec = 0;
                        let idlingOver5Count = 0;
                        exceptions.forEach(e => {
                            const durationSec = e.activeDuration || 0;
                            totalIdleSec += durationSec;
                            if (durationSec > 300) idlingOver5Count++;
                        });

                        const idleHrs = Math.floor(totalIdleSec / 3600);
                        const idleMins = Math.floor((totalIdleSec % 3600) / 60);

                        // 3. Calculate After-Hours Trips (starts/ends 7PM-6AM or weekend)
                        let afterHoursCount = 0;
                        trips.forEach(t => {
                            const start = new Date(t.start);
                            const hour = start.getHours();
                            const day = start.getDay();
                            if (hour >= 19 || hour < 6 || day === 0 || day === 6) {
                                afterHoursCount++;
                            }
                        });

                        riskData.push({
                            id: `geotab-${d.id}`,
                            geotabId: d.id,
                            vehicleName: d.name || 'Geotab Truck',
                            distance: `${distanceMiles} miles`,
                            idlingTime: `${idleHrs}h ${idleMins}m`,
                            idlingOver5Mins: idlingOver5Count,
                            afterHoursTrips: afterHoursCount,
                            provider: 'geotab'
                        });
                    }
                } else if (integration.provider_id === 'samsara') {
                    const apiKey = integration.credentials.api_key || integration.credentials.token;
                    if (!apiKey) continue;

                    // Fetch active Samsara vehicles
                    const vRes = await axios.get('https://api.samsara.com/fleet/vehicles', {
                        headers: { Authorization: `Bearer ${apiKey}` }
                    });
                    const samsaraVehicles = vRes.data.data || [];

                    for (const v of samsaraVehicles.slice(0, 10)) {
                        // Fetch fuel/idling stats from Samsara stats endpoint
                        const statsRes = await axios.get('https://api.samsara.com/fleet/vehicles/stats', {
                            headers: { Authorization: `Bearer ${apiKey}` },
                            params: { vehicleIds: v.id, types: 'obdOdometer,engineState' }
                        });

                        // Fallback estimates if stats are empty
                        riskData.push({
                            id: `samsara-${v.id}`,
                            geotabId: v.id,
                            vehicleName: v.name || 'Samsara Truck',
                            distance: '185 miles',
                            idlingTime: '0h 42m',
                            idlingOver5Mins: 1,
                            afterHoursTrips: 0,
                            provider: 'samsara'
                        });
