app.post('/api/geotab-speed-profile', async (req, res) => {
    try {
        const { deviceId, organizationId, timeframe } = req.body;

        if (!organizationId || !deviceId) {
            return res.json({ success: false, error: 'Missing parameters' });
        }

        const { data: integrations, error: integrationErr } = await supabase
          .from('fleet_integrations')
          .select('provider_id, credentials')
          .eq('organization_id', organizationId)
          .eq('status', 'connected');

        if (integrationErr || !integrations || integrations.length === 0) {
            return res.json({ success: false, error: 'Integration credentials not found' });
        }

        const toDate = new Date();
        const fromDate = new Date();
        if (timeframe === '7d') {
            fromDate.setDate(fromDate.getDate() - 7);
        } else if (timeframe === '30d') {
            fromDate.setDate(fromDate.getDate() - 30);
        } else {
            fromDate.setHours(fromDate.getHours() - 24);
        }

        // Check provider dynamically based on deviceId prefix or scan integration list
        const isSamsaraDevice = deviceId.startsWith('samsara-') || deviceId.match(/^\d+$/);
        const provider = isSamsaraDevice
            ? integrations.find(p => p.provider_id === 'samsara')
            : integrations.find(p => p.provider_id === 'geotab') || integrations[0];

        if (!provider) {
            return res.json({ success: true, data: [] });
        }

        console.log(`📡 [DEBUG] Speed Profile calling provider: ${provider.provider_id} for device: ${deviceId}`);

        if (provider.provider_id === 'geotab') {
            const { username, password, database } = provider.credentials;
            const auth = await axios.post("https://my.geotab.com/apiv1", {
                method: "Authenticate",
                params: { userName: username, password: password, database: database }
            });

            if (auth.data.error) throw new Error(auth.data.error.message);

            const credentials = auth.data.result.credentials;
            const serverPath = auth.data.result.path === "ThisServer" ? "my.geotab.com" : auth.data.result.path;

            // Resolve real device ID (in case deviceId is a name)
            let devices = [];
            const cleanId = deviceId.replace('geotab-', '');
            const byId = await axios.post(`https://${serverPath}/apiv1`, {
                method: "Get",
                params: { typeName: "Device", search: { id: cleanId }, credentials }
            });
            devices = byId.data.result || [];

            if (devices.length === 0) {
                const byName = await axios.post(`https://${serverPath}/apiv1`, {
                    method: "Get",
                    params: { typeName: "Device", search: { name: cleanId }, credentials }
                });
                devices = byName.data.result || [];
            }

            if (devices.length === 0) return res.json({ success: true, data: [] });
            const realId = devices[0].id;

            const response = await axios.post(`https://${serverPath}/apiv1`, {
                method: "Get",
                params: {
                    typeName: "LogRecord",
                    search: {
                        deviceSearch: { id: realId },
                        fromDate: fromDate.toISOString(),
                        toDate: toDate.toISOString()
                    },
                    resultsLimit: 2000,
                    credentials
                }
            });

            const logs = response.data.result || [];
            const data = logs.map(l => {
                const dateObj = new Date(l.dateTime);
                const kmh = Math.round(l.speed);
                return {
                    timestamp: dateObj.getTime(),
                    time: dateObj.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}),
                    speed: kmh,
                    speedLimit: 100,
                    speedLimitEst: 105
                };
            });

            console.log(`✅ [DEBUG] Speed Profile Geotab returned: ${data.length} records`);
            return res.json({ success: true, data });
        } else if (provider.provider_id === 'samsara') {
            const apiKey = provider.credentials.api_key || provider.credentials.token;
            if (!apiKey) return res.json({ success: true, data: [] });

            const cleanId = deviceId.replace('samsara-', '');
            // Query Samsara's location history to extract speed profiles
            const response = await axios.get('https://api.samsara.com/fleet/vehicles/locations/history', {
                headers: { Authorization: `Bearer ${apiKey}` },
                params: {
                    vehicleIds: cleanId,
                    startTime: fromDate.toISOString(),
                    endTime: toDate.toISOString()
                }
            });

            const points = response.data.data || [];
            const data = [];

            points.forEach(vehicleData => {
                const locations = vehicleData.locations || [];
                locations.forEach(loc => {
                    const dateObj = new Date(loc.time);
                    const speedMps = loc.speed || 0;
                    const speedKmh = Math.round(speedMps * 3.6); // Convert m/s to km/h
                    data.push({
                        timestamp: dateObj.getTime(),
                        time: dateObj.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}),
                        speed: speedKmh,
                        speedLimit: 90,
                        speedLimitEst: 95
                    });
                });
            });

            // Sort by timestamp
            data.sort((a, b) => a.timestamp - b.timestamp);

            console.log(`✅ [DEBUG] Speed Profile Samsara returned: ${data.length} records`);
            return res.json({ success: true, data });
        }

