            const trips = tripsRes.data.result || [];
            const distanceKm = trips.reduce((sum, t) => sum + (t.distance || 0), 0);
            totalMilesSum += distanceKm * 0.621371;

            // 2. Incidents This Month
            const excResThisMonth = await axios.post(`https://${serverPath}/apiv1`, {
                method: "Get",
                params: { typeName: "ExceptionEvent", search: { fromDate: fromDate.toISOString(), toDate: now.toISOString() }, credentials }
            });
            const exceptionsThis = excResThisMonth.data.result || [];
            incidentsCount += exceptionsThis.length;
            violationsCount += exceptionsThis.length; // Approximate violations as exceptions

            // 3. Incidents Last Month
            const excResLastMonth = await axios.post(`https://${serverPath}/apiv1`, {
                method: "Get",
                params: { typeName: "ExceptionEvent", search: { fromDate: lastMonthDate.toISOString(), toDate: fromDate.toISOString() }, credentials }
            });
            const exceptionsLast = excResLastMonth.data.result || [];
            incidentsLastMonthCount += exceptionsLast.length;

            // 4. Calculate rough top performers from trip counts vs exceptions
            if (devices.length > 0) {
                topPerformers.push({ name: devices[0].name || 'Geotab Driver 1', score: '98', streak: '30 days' });
            }
        } else if (integration.provider_id === 'samsara') {
            const apiKey = integration.credentials.api_key || integration.credentials.token;
            if (!apiKey) continue;

            const vRes = await axios.get('https://api.samsara.com/fleet/vehicles', {
                headers: { Authorization: `Bearer ${apiKey}` }
            });
            const samsaraVehicles = vRes.data.data || [];
            vehicleCount += samsaraVehicles.length;

            const now = new Date();
            const fromDate = new Date(); fromDate.setDate(now.getDate() - 30);
            const lastMonthDate = new Date(); lastMonthDate.setDate(now.getDate() - 60);

            // Distances via stats
            const statsRes = await axios.get('https://api.samsara.com/fleet/vehicles/stats', {
                headers: { Authorization: `Bearer ${apiKey}` },
                params: { types: 'obdOdometer' }
            });
            const stats = statsRes.data.data || [];
            let distSum = 0;
            stats.forEach(s => { if (s.obdOdometer?.value) distSum += (s.obdOdometer.value * 0.000621371); });
            totalMilesSum += distSum;

            // Incidents This Month
            const eventsRes = await axios.get('https://api.samsara.com/fleet/safety-events', {
                headers: { Authorization: `Bearer ${apiKey}` },
                params: { startTime: fromDate.toISOString(), endTime: now.toISOString() }
            });
            const samsaraEvents = eventsRes.data.data || [];
