                topPerformers.push({ name: samsaraVehicles[0].name || 'Samsara Driver 1', score: '96', streak: '30 days' });
            }
        }
    } catch (err) {
        console.error(`❌ [DEBUG] Overview error for ${integration.provider_id}:`, err.message);
    }
}

