if (totalMilesSum > 0) {
    // Rough heuristic: start at 100, subtract 2 points per incident per 1000 miles
    const deduction = (incidentsCount / (totalMilesSum / 1000)) * 2;
    avgSafetyScore = Math.max(0, Math.min(100, 100 - deduction));
} else if (incidentsCount > 0) {
