for (const v of samsaraVehicles.slice(0, 10)) {
    // Fetch stats (distance)
    const statsRes = await axios.get('https://api.samsara.com/fleet/vehicles/stats', {
        headers: { Authorization: `Bearer ${apiKey}` },
        params: { vehicleIds: v.id, types: 'obdOdometer,gpsOdometer' }
    });

    const stat = statsRes.data.data && statsRes.data.data.length > 0 ? statsRes.data.data[0] : null;
    let distanceMiles = 0;
    if (stat) {
        const odo = stat.obdOdometer?.value || stat.gpsOdometer?.value || 0;
        distanceMiles = Math.round(odo * 0.000621371); // meters to miles
    }

    // Fetch idling history
    const idleRes = await axios.get('https://api.samsara.com/fleet/vehicles/stats/history', {
        headers: { Authorization: `Bearer ${apiKey}` },
        params: { vehicleIds: v.id, types: 'engineStates', startTime: fromDate.toISOString(), endTime: toDate.toISOString() }
    });

    let totalIdleSec = 0;
    let idlingOver5Mins = 0;
    const idleHistory = idleRes.data.data && idleRes.data.data.length > 0 ? idleRes.data.data[0].engineStates : [];
    if (idleHistory && idleHistory.length > 0) {
        for (let i = 0; i < idleHistory.length - 1; i++) {
            if (idleHistory[i].value === 'Idle') {
                const idleDurationSec = (new Date(idleHistory[i+1].time).getTime() - new Date(idleHistory[i].time).getTime()) / 1000;
                totalIdleSec += idleDurationSec;
                if (idleDurationSec > 300) idlingOver5Mins++;
            }
        }
    }

